-- China 1928: unique units and buildings of the six sides, cloned from the stock rows at load time, and the ability whose
-- stock effect is dead in the scenario (generated by text/build_text.py from text/uniques.py).
-- The donor civilizations' own uniques are unhooked; stock 3D models, icons, techs and upgrade paths are kept.

-- Central Army Division (NAN): UNIT_GREAT_WAR_INFANTRY
CREATE TEMP TABLE tmp_u AS SELECT * FROM Units WHERE Type = 'UNIT_GREAT_WAR_INFANTRY';
UPDATE tmp_u SET ID = (SELECT MAX(ID) + 1 FROM Units), Type = 'UNIT_CHN1928_CENTRAL_ARMY', Description = 'TXT_KEY_UNIT_CHN1928_CENTRAL_ARMY', Civilopedia = 'TXT_KEY_CIV5_CHN1928_CENTRAL_ARMY_TEXT', Strategy = 'TXT_KEY_UNIT_CHN1928_CENTRAL_ARMY_STRATEGY', Help = 'TXT_KEY_UNIT_CHN1928_CENTRAL_ARMY_HELP', Combat = 55, Cost = 360;

